style.css:
@-moz-document domain("youtube.com") {
/* =========================================================
   YOUTUBE V3 — GOLD INFERNO / CINEMATIC HOME
   - fond plus visible / flou léger
   - layout plus aéré type zoom 75% visuel
   - homepage plus propre
   - miniatures avec overlay premium
   - logo custom + ambiance anime luxury
   ========================================================= */

:root {
  /* =========================
     IMAGES
     ========================= */
  --bg-image: url("https://i.pinimg.com/736x/7b/b5/f3/7bb5f3b2fc16772063498fa4ad9d0aa1.jpg");
  --custom-logo: url("https://i.imgur.com/6sKQEi6.png");

  /* =========================
     PALETTE
     ========================= */
  --bg-0: #050505;
  --bg-1: #0a0a0d;
  --bg-2: #111116;
  --bg-3: #17171d;

  --glass: rgba(10, 10, 12, 0.58);
  --glass-2: rgba(14, 14, 18, 0.68);
  --glass-3: rgba(18, 18, 24, 0.50);
  --glass-soft: rgba(10, 10, 12, 0.40);

  --gold: #f6c76e;
  --gold-2: #ffd27f;
  --gold-3: #e6ac4d;
  --copper: #d56d2d;
  --orange: #ff7d34;
  --fire: #ff9c50;
  --ember: #ffb66e;

  --text: #f8f3ea;
  --text-soft: #ddd3c6;
  --text-muted: #b7ad9e;

  --border: rgba(255, 201, 110, 0.16);
  --border-strong: rgba(255, 201, 110, 0.32);

  --shadow-dark: 0 18px 46px rgba(0,0,0,0.42);
  --shadow-gold: 0 0 22px rgba(255, 191, 95, 0.10);
  --shadow-orange: 0 0 26px rgba(255, 125, 52, 0.10);

  --radius-xl: 24px;
  --radius-lg: 18px;
  --radius-md: 14px;
  --radius-sm: 10px;

  --tr: .28s ease;
}

/* =========================================================
   BASE
   ========================================================= */

html,
body,
ytd-app,
#content.ytd-app,
#page-manager,
ytd-browse,
ytd-watch-flexy,
ytd-two-column-browse-results-renderer {
  background: transparent !important;
  color: var(--text) !important;
}

/* =========================================================
   FOND — PLUS VISIBLE / FLOU LÉGER / MOINS OPAQUE
   ========================================================= */

body::before {
  content: "";
  position: fixed;
  inset: 0;
  background:
    linear-gradient(135deg, rgba(0,0,0,0.50), rgba(12,8,5,0.42)),
    radial-gradient(circle at 78% 20%, rgba(255,125,52,0.14), transparent 24%),
    radial-gradient(circle at 20% 30%, rgba(246,199,110,0.09), transparent 28%),
    radial-gradient(circle at 70% 80%, rgba(213,109,45,0.07), transparent 26%),
    var(--bg-image) center center / cover no-repeat !important;
  filter: blur(5px) saturate(1.08) brightness(0.76) contrast(1.02);
  transform: scale(1.03);
  z-index: -9999;
  pointer-events: none;
}

/* voile très léger pour garder la lisibilité */
body::after {
  content: "";
  position: fixed;
  inset: 0;
  background:
    linear-gradient(180deg, rgba(4,4,4,0.06), rgba(4,4,4,0.18)),
    linear-gradient(120deg, rgba(255,191,95,0.03), transparent 35%, transparent 70%, rgba(255,125,52,0.03));
  z-index: -9998;
  pointer-events: none;
}

/* =========================================================
   TOP BAR
   ========================================================= */

ytd-masthead,
#masthead-container,
tp-yt-app-header-layout {
  background: rgba(7, 7, 10, 0.40) !important;
  backdrop-filter: blur(14px) saturate(1.08) !important;
  -webkit-backdrop-filter: blur(14px) saturate(1.08) !important;
  border-bottom: 1px solid var(--border) !important;
  box-shadow: 0 8px 24px rgba(0,0,0,0.20) !important;
}

/* =========================================================
   LOGO CUSTOM
   ========================================================= */

ytd-topbar-logo-renderer #logo-icon,
ytd-topbar-logo-renderer yt-icon,
ytd-topbar-logo-renderer svg,
a#logo svg {
  opacity: 0 !important;
  visibility: hidden !important;
}

ytd-topbar-logo-renderer a#logo,
a#logo {
  position: relative !important;
  width: 158px !important;
  min-width: 158px !important;
  height: 50px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: flex-start !important;
  overflow: visible !important;
}

ytd-topbar-logo-renderer a#logo::before,
a#logo::before {
  content: "";
  position: absolute;
  left: 4px;
  top: 50%;
  transform: translateY(-50%);
  width: 132px;
  height: 44px;
  background: var(--custom-logo) center / contain no-repeat;
  z-index: 5;
  filter:
    drop-shadow(0 0 10px rgba(255, 191, 95, 0.18))
    drop-shadow(0 0 18px rgba(255, 125, 52, 0.14));
  transition: transform .25s ease, filter .25s ease;
}

ytd-topbar-logo-renderer a#logo::after,
a#logo::after {
  content: "";
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 142px;
  height: 50px;
  border-radius: 16px;
  background:
    radial-gradient(circle at 35% 50%, rgba(255,201,110,0.10), transparent 55%),
    radial-gradient(circle at 70% 50%, rgba(255,125,52,0.08), transparent 60%);
  box-shadow:
    0 0 16px rgba(255,191,95,0.08),
    0 0 24px rgba(255,125,52,0.06);
  pointer-events: none;
  z-index: 4;
}

ytd-topbar-logo-renderer a#logo:hover::before,
a#logo:hover::before {
  transform: translateY(-50%) scale(1.03);
  filter:
    drop-shadow(0 0 14px rgba(255,191,95,0.24))
    drop-shadow(0 0 24px rgba(255,125,52,0.18));
}

/* =========================================================
   SIDEBAR
   ========================================================= */

ytd-guide-renderer,
#guide-content,
ytd-mini-guide-renderer {
  background: rgba(8, 8, 10, 0.36) !important;
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
  border-right: 1px solid rgba(255,201,110,0.08) !important;
}

ytd-guide-entry-renderer,
ytd-mini-guide-entry-renderer,
tp-yt-paper-item {
  border-radius: 14px !important;
  margin: 3px 8px !important;
  transition: var(--tr) !important;
}

ytd-guide-entry-renderer:hover,
ytd-mini-guide-entry-renderer:hover,
tp-yt-paper-item:hover {
  background: linear-gradient(90deg, rgba(246,199,110,0.08), rgba(255,125,52,0.05)) !important;
  box-shadow: inset 0 0 0 1px rgba(255,201,110,0.08) !important;
  transform: translateX(2px);
}

ytd-guide-entry-renderer[active],
ytd-mini-guide-entry-renderer[active] {
  background: linear-gradient(90deg, rgba(246,199,110,0.14), rgba(213,109,45,0.10)) !important;
  box-shadow:
    inset 0 0 0 1px rgba(255,201,110,0.16),
    0 0 16px rgba(255,191,95,0.06) !important;
}

ytd-guide-entry-renderer yt-icon,
ytd-mini-guide-entry-renderer yt-icon,
#guide-icon {
  color: var(--gold) !important;
}

/* =========================================================
   SEARCH BAR
   ========================================================= */

ytd-searchbox,
#search-form,
#search,
#container.ytd-searchbox,
yt-searchbox,
input#search {
  background: rgba(14, 14, 18, 0.58) !important;
  border: 1px solid rgba(255,201,110,0.18) !important;
  border-radius: 999px !important;
  color: var(--text) !important;
  transition: var(--tr) !important;
}

#search-form:focus-within,
#container.ytd-searchbox:focus-within,
ytd-searchbox:focus-within {
  border-color: var(--border-strong) !important;
  box-shadow:
    0 0 0 1px rgba(255,201,110,0.18),
    0 0 20px rgba(255,191,95,0.08) !important;
}

input#search,
#search-input input {
  color: var(--text) !important;
}
input#search::placeholder {
  color: var(--text-muted) !important;
}

#search-icon-legacy {
  background: linear-gradient(135deg, rgba(246,199,110,0.12), rgba(213,109,45,0.10)) !important;
  border-left: 1px solid rgba(255,201,110,0.12) !important;
  color: var(--gold) !important;
  border-radius: 0 999px 999px 0 !important;
}

/* =========================================================
   TEXTES
   ========================================================= */

yt-formatted-string,
#text,
#title,
#video-title,
#channel-name,
#owner-name,
#description,
#metadata-line,
#subscriber-count,
#info-text,
#author-text,
h1, h2, h3 {
  color: var(--text) !important;
}

#video-title,
#title a,
#video-title-link,
ytd-rich-grid-media #video-title,
ytd-video-renderer #video-title {
  color: #fff6e8 !important;
  font-weight: 700 !important;
  letter-spacing: 0.1px !important;
}

#video-title:hover,
#title a:hover,
#video-title-link:hover {
  color: var(--gold) !important;
}

#metadata-line,
#metadata-line span,
#channel-name a,
#owner-name a,
#byline,
#description-text,
.yt-core-attributed-string {
  color: var(--text-soft) !important;
}

/* =========================================================
   EFFET "ZOOM 75%" VISUEL / PAGE PLUS AÉRÉE
   IMPORTANT :
   on ne change pas le vrai zoom navigateur, on crée
   un rendu visuel plus compact pour mieux voir le fond
   ========================================================= */

/* Homepage : contenu un peu réduit */
ytd-rich-grid-renderer {
  transform: scale(0.92) !important;
  transform-origin: top center !important;
  width: 108% !important;
  margin-left: -4% !important;
  margin-top: -18px !important;
}

/* page watch un peu plus compacte */
ytd-watch-flexy #columns {
  transform: scale(0.94) !important;
  transform-origin: top center !important;
  width: 106% !important;
  margin-left: -3% !important;
}

/* mini-guide / sidebar pour garder l'équilibre */
#guide-content,
ytd-guide-renderer {
  zoom: 0.96;
}

/* =========================================================
   HOMEPAGE PLUS PROPRE / ESPACEMENT
   ========================================================= */

ytd-rich-grid-renderer,
#contents.ytd-rich-grid-renderer {
  background: transparent !important;
}

/* espace plus respirant */
ytd-rich-item-renderer {
  margin-top: 8px !important;
  margin-bottom: 16px !important;
}

/* cartes vidéo plus premium */
ytd-rich-item-renderer,
ytd-video-renderer,
ytd-grid-video-renderer,
ytd-compact-video-renderer,
ytd-playlist-renderer,
ytd-playlist-video-renderer,
ytd-comment-thread-renderer,
ytd-watch-metadata,
ytd-playlist-panel-renderer,
ytd-compact-playlist-renderer,
#below,
#secondary-inner,
ytd-comments {
  background: var(--glass-soft) !important;
  border: 1px solid var(--border) !important;
  border-radius: 20px !important;
  backdrop-filter: blur(10px) !important;
  -webkit-backdrop-filter: blur(10px) !important;
  box-shadow: var(--shadow-dark) !important;
  transition: transform var(--tr), box-shadow var(--tr), border-color var(--tr) !important;
}

/* hover plus propre */
ytd-rich-item-renderer:hover,
ytd-video-renderer:hover,
ytd-grid-video-renderer:hover,
ytd-compact-video-renderer:hover,
ytd-playlist-renderer:hover,
ytd-playlist-video-renderer:hover {
  transform: translateY(-5px) !important;
  border-color: rgba(255,201,110,0.28) !important;
  box-shadow:
    0 18px 40px rgba(0,0,0,0.30),
    0 0 22px rgba(255,191,95,0.07),
    0 0 18px rgba(255,125,52,0.05) !important;
}

/* =========================================================
   MINIATURES PREMIUM + OVERLAY
   ========================================================= */

ytd-thumbnail,
ytd-playlist-thumbnail,
yt-image,
#thumbnail,
#thumbnail-container {
  position: relative !important;
  border-radius: 20px !important;
  overflow: hidden !important;
  box-shadow:
    0 12px 30px rgba(0,0,0,0.28),
    0 0 0 1px rgba(255,201,110,0.10) !important;
}

/* image thumbnail */
ytd-thumbnail img,
yt-image img,
#thumbnail img {
  transition: transform .38s ease, filter .38s ease !important;
  filter: saturate(1.08) contrast(1.03) brightness(0.97) !important;
}

/* hover image */
ytd-rich-item-renderer:hover ytd-thumbnail img,
ytd-video-renderer:hover ytd-thumbnail img,
ytd-grid-video-renderer:hover ytd-thumbnail img {
  transform: scale(1.05) !important;
  filter: saturate(1.14) contrast(1.05) brightness(1.01) !important;
}

/* overlay premium léger */
ytd-thumbnail::before,
#thumbnail::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 2;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.03), transparent 28%, transparent 60%, rgba(0,0,0,0.18)),
    linear-gradient(135deg, rgba(255,201,110,0.08), transparent 38%, transparent 70%, rgba(255,125,52,0.08));
  pointer-events: none;
  transition: opacity .28s ease;
}

/* contour premium */
ytd-thumbnail::after,
#thumbnail::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 3;
  border-radius: 20px;
  box-shadow:
    inset 0 0 0 1px rgba(255,201,110,0.16),
    inset 0 -24px 35px rgba(0,0,0,0.10);
  pointer-events: none;
}

/* hover overlay */
ytd-rich-item-renderer:hover ytd-thumbnail::before,
ytd-video-renderer:hover ytd-thumbnail::before,
ytd-grid-video-renderer:hover ytd-thumbnail::before {
  background:
    linear-gradient(180deg, rgba(255,255,255,0.04), transparent 24%, transparent 58%, rgba(0,0,0,0.20)),
    linear-gradient(135deg, rgba(255,201,110,0.12), transparent 35%, transparent 68%, rgba(255,125,52,0.10));
}

/* durée vidéo plus jolie */
.ytd-thumbnail-overlay-time-status-renderer,
.badge,
.ytp-ce-video-duration {
  background: rgba(7,7,10,0.62) !important;
  color: #fff4df !important;
  border: 1px solid rgba(255,201,110,0.14) !important;
  border-radius: 10px !important;
  backdrop-filter: blur(6px) !important;
}

/* =========================================================
   BOUTONS / CHIPS
   ========================================================= */

button,
yt-button-shape button,
tp-yt-paper-button,
yt-spec-button-shape-next,
yt-chip-cloud-chip-renderer {
  border-radius: 999px !important;
  transition: var(--tr) !important;
}

button,
yt-button-shape button,
tp-yt-paper-button,
yt-spec-button-shape-next {
  background: linear-gradient(135deg, rgba(246,199,110,0.10), rgba(213,109,45,0.09)) !important;
  color: var(--text) !important;
  border: 1px solid rgba(255,201,110,0.15) !important;
  box-shadow: 0 6px 18px rgba(0,0,0,0.18) !important;
}

button:hover,
yt-button-shape button:hover,
tp-yt-paper-button:hover,
yt-spec-button-shape-next:hover {
  transform: translateY(-1px) !important;
  border-color: rgba(255,201,110,0.28) !important;
  box-shadow:
    0 10px 24px rgba(0,0,0,0.22),
    0 0 16px rgba(255,191,95,0.06) !important;
}

ytd-subscribe-button-renderer button,
ytd-button-renderer[is-paper-button] button {
  background: linear-gradient(135deg, #f6c76e, #d56d2d) !important;
  color: #140e08 !important;
  font-weight: 800 !important;
  border: none !important;
  box-shadow:
    0 8px 24px rgba(213,109,45,0.24),
    0 0 18px rgba(255,201,110,0.12) !important;
}

yt-chip-cloud-chip-renderer {
  background: rgba(255,255,255,0.035) !important;
  border: 1px solid rgba(255,201,110,0.12) !important;
  color: var(--text-soft) !important;
}
yt-chip-cloud-chip-renderer[selected] {
  background: linear-gradient(135deg, rgba(246,199,110,0.18), rgba(213,109,45,0.14)) !important;
  border-color: rgba(255,201,110,0.28) !important;
  color: #fff4df !important;
}

/* =========================================================
   PAGE VIDÉO / PLAYER
   ========================================================= */

#below,
#secondary-inner,
ytd-watch-metadata,
ytd-comments,
ytd-playlist-panel-renderer {
  background: var(--glass-2) !important;
  border-radius: var(--radius-xl) !important;
}

.html5-video-player,
#movie_player {
  border-radius: 24px !important;
  overflow: hidden !important;
  box-shadow:
    0 18px 50px rgba(0,0,0,0.40),
    0 0 26px rgba(255,191,95,0.06) !important;
  border: 1px solid rgba(255,201,110,0.14) !important;
}

.ytp-chrome-bottom,
.ytp-tooltip,
.ytp-popup,
.ytp-settings-menu {
  background: rgba(8, 8, 12, 0.60) !important;
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
  border: 1px solid rgba(255,201,110,0.10) !important;
}

.ytp-play-progress {
  background: linear-gradient(90deg, #f6c76e, #ff9c50) !important;
}
.ytp-load-progress {
  background: rgba(255,255,255,0.16) !important;
}

/* =========================================================
   COMMENTAIRES / POPUPS
   ========================================================= */

#contenteditable-root,
ytd-commentbox,
ytd-comment-thread-renderer #body,
ytd-comment-renderer #body {
  color: var(--text) !important;
}

ytd-commentbox #contenteditable-root,
#simplebox-placeholder,
#contenteditable-root {
  background: rgba(255,255,255,0.025) !important;
  border: 1px solid rgba(255,201,110,0.10) !important;
  border-radius: 14px !important;
}

tp-yt-paper-dialog,
ytd-menu-popup-renderer,
tp-yt-iron-dropdown,
.ytp-popup,
yt-confirm-dialog-renderer {
  background: rgba(10,10,14,0.82) !important;
  backdrop-filter: blur(14px) !important;
  -webkit-backdrop-filter: blur(14px) !important;
  border: 1px solid rgba(255,201,110,0.12) !important;
  border-radius: 18px !important;
  box-shadow:
    0 18px 40px rgba(0,0,0,0.38),
    0 0 22px rgba(255,191,95,0.06) !important;
}

/* =========================================================
   LIENS / TOOLTIPS / SCROLLBAR
   ========================================================= */

a,
a:visited,
yt-formatted-string a {
  color: #ffd896 !important;
  transition: var(--tr) !important;
}
a:hover,
yt-formatted-string a:hover {
  color: #fff1d0 !important;
  text-shadow: 0 0 8px rgba(255,201,110,0.16) !important;
}

tp-yt-paper-toast,
.ytp-tooltip,
yt-tooltip-renderer {
  background: rgba(12,12,16,0.80) !important;
  color: #fff4df !important;
  border: 1px solid rgba(255,201,110,0.12) !important;
  border-radius: 12px !important;
}

::-webkit-scrollbar {
  width: 10px !important;
  height: 10px !important;
}
::-webkit-scrollbar-track {
  background: rgba(0,0,0,0.20) !important;
}
::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, rgba(246,199,110,0.68), rgba(213,109,45,0.64)) !important;
  border-radius: 999px !important;
  border: 2px solid rgba(10,10,10,0.28) !important;
}
::-webkit-scrollbar-thumb:hover {
  background: linear-gradient(180deg, rgba(255,210,126,0.88), rgba(255,125,52,0.86)) !important;
}

/* =========================================================
   CLEANUP
   ========================================================= */

#background,
#chips-wrapper,
#header,
#container,
#main,
#sections,
#contents,
ytd-page-manager {
  background-color: transparent !important;
}

hr,
#separator {
  border-color: rgba(255,201,110,0.06) !important;
}
}
